CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER create_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='admin'), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE TABLE public.businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100), sector text NOT NULL DEFAULT 'Comércio', phone text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id));
GRANT SELECT ON public.businesses TO authenticated; GRANT ALL ON public.businesses TO service_role;
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_read ON public.businesses FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.owns_business(b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.businesses WHERE id=b AND owner_id=auth.uid()) $$;
CREATE TABLE public.plans(id text PRIMARY KEY, name text NOT NULL, price numeric(14,2) NOT NULL CHECK(price>0), duration_days integer NOT NULL CHECK(duration_days>0), enabled boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.plans TO authenticated; GRANT ALL ON public.plans TO service_role;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY plan_read ON public.plans FOR SELECT TO authenticated USING(true);
CREATE TABLE public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), plan_id text REFERENCES public.plans(id), starts_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, is_trial boolean NOT NULL DEFAULT false, CHECK(expires_at>starts_at));
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscription_read ON public.subscriptions FOR SELECT TO authenticated USING(public.owns_business(business_id) OR public.is_admin());
CREATE FUNCTION public.business_active(b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.owns_business(b) AND EXISTS(SELECT 1 FROM public.subscriptions WHERE business_id=b AND starts_at<=now() AND expires_at>now()) $$;
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150), sku text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Geral', cost numeric(14,2) NOT NULL DEFAULT 0 CHECK(cost>=0), price numeric(14,2) NOT NULL CHECK(price>=0), stock numeric(14,3) NOT NULL DEFAULT 0 CHECK(stock>=0), min_stock numeric(14,3) NOT NULL DEFAULT 5 CHECK(min_stock>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,business_id));
CREATE TABLE public.customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,business_id));
CREATE TABLE public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,business_id));
CREATE TABLE public.sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),customer_id uuid, total numeric(14,2) NOT NULL CHECK(total>=0),discount numeric(14,2) NOT NULL DEFAULT 0 CHECK(discount>=0),paid numeric(14,2) NOT NULL CHECK(paid>=0 AND paid<=total),payment_method text NOT NULL CHECK(payment_method IN ('Dinheiro','Transferência','TPA','Crédito')),status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','reversed')),reversal_reason text,created_at timestamptz NOT NULL DEFAULT now(), request_id uuid NOT NULL UNIQUE,UNIQUE(id,business_id),FOREIGN KEY(customer_id,business_id) REFERENCES public.customers(id,business_id));
CREATE TABLE public.sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),sale_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(14,3) NOT NULL CHECK(quantity>0),unit_price numeric(14,2) NOT NULL CHECK(unit_price>=0),unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),FOREIGN KEY(sale_id,business_id) REFERENCES public.sales(id,business_id),FOREIGN KEY(product_id,business_id) REFERENCES public.products(id,business_id));
CREATE TABLE public.inventory_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),product_id uuid NOT NULL,quantity numeric(14,3) NOT NULL CHECK(quantity<>0),kind text NOT NULL CHECK(kind IN ('opening','sale','purchase','reversal','adjustment')),notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(product_id,business_id) REFERENCES public.products(id,business_id));
CREATE TABLE public.expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),category text NOT NULL CHECK(length(category) BETWEEN 1 AND 100),amount numeric(14,2) NOT NULL CHECK(amount>0),expense_date date NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Luanda')::date,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=1000),receipt_path text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.receivables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),customer_id uuid NOT NULL,sale_id uuid NOT NULL UNIQUE,amount numeric(14,2) NOT NULL CHECK(amount>0),paid numeric(14,2) NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=amount),due_date date NOT NULL, cancelled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,business_id),FOREIGN KEY(customer_id,business_id) REFERENCES public.customers(id,business_id),FOREIGN KEY(sale_id,business_id) REFERENCES public.sales(id,business_id));
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),receivable_id uuid NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>0),method text NOT NULL DEFAULT 'Dinheiro',created_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL UNIQUE,FOREIGN KEY(receivable_id,business_id) REFERENCES public.receivables(id,business_id));
CREATE TABLE public.purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),supplier_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(14,3) NOT NULL CHECK(quantity>0),unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),paid numeric(14,2) NOT NULL CHECK(paid>=0),created_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL UNIQUE,FOREIGN KEY(supplier_id,business_id) REFERENCES public.suppliers(id,business_id),FOREIGN KEY(product_id,business_id) REFERENCES public.products(id,business_id),CHECK(paid<=quantity*unit_cost));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),message text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.payment_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),bank_name text NOT NULL DEFAULT '',account_holder text NOT NULL DEFAULT '',iban text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_settings TO authenticated; GRANT ALL ON public.payment_settings TO service_role;
ALTER TABLE public.payment_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.payment_settings FOR SELECT TO authenticated USING(true);
CREATE TABLE public.payment_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),plan_id text NOT NULL REFERENCES public.plans(id),reference text NOT NULL CHECK(length(reference) BETWEEN 3 AND 100),receipt_path text,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewed_by uuid REFERENCES public.profiles(id),reviewed_at timestamptz,review_note text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(reference));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid REFERENCES public.businesses(id),actor_id uuid REFERENCES public.profiles(id),event text NOT NULL,record_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.is_admin());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products','customers','suppliers','sales','sale_items','inventory_movements','expenses','receivables','payments','purchases','notifications','payment_requests'] LOOP EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_read ON public.%I FOR SELECT TO authenticated USING(public.owns_business(business_id) OR public.is_admin())',t); END LOOP; END $$;
CREATE POLICY receipt_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='receipts' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY receipt_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='receipts' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_admin()));
CREATE INDEX product_business_idx ON public.products(business_id);
CREATE INDEX sales_business_date_idx ON public.sales(business_id,created_at);
CREATE INDEX receivable_business_idx ON public.receivables(business_id);
CREATE FUNCTION public.onboard_business(p_name text,p_sector text,p_phone text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão necessária'; END IF; INSERT INTO public.businesses(owner_id,name,sector,phone) VALUES(auth.uid(),trim(p_name),left(p_sector,100),left(p_phone,30)) RETURNING id INTO b; INSERT INTO public.subscriptions(business_id,starts_at,expires_at,is_trial) VALUES(b,now(),now()+interval '7 days',true); RETURN b; END $$;
REVOKE ALL ON FUNCTION public.onboard_business(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.onboard_business(text,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.create_profile() FROM PUBLIC,anon,authenticated;